begin;
create table public.profiles(id uuid primary key references auth.users(id), nome text not null, cpf text unique not null check(cpf ~ '^[0-9]{11}$'), telefone text, nascimento date, funcao text check(funcao in ('Auxiliar de Limpeza','Recepcionista','Porteiro')), status text not null default 'Pendente' check(status in ('Pendente','Ativo','Reprovado','Inativo')), ciencia_privacidade timestamptz not null default now());
create table public.user_roles(user_id uuid primary key references auth.users(id), role text not null check(role in ('admin','colaborador')));
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin') $$;
create function public.is_active() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and status='Ativo') $$;
create table public.postos(id uuid primary key default gen_random_uuid(), nome text not null, cliente text not null, endereco text not null, latitude double precision not null check(latitude between -90 and 90), longitude double precision not null check(longitude between -180 and 180), raio integer not null default 100 check(raio>0), horario text, vagas jsonb not null default '{}');
create table public.vinculos(id uuid primary key default gen_random_uuid(), colaborador_id uuid not null references public.profiles(id), posto_id uuid not null references public.postos(id), funcao text not null check(funcao in ('Auxiliar de Limpeza','Recepcionista','Porteiro')), turno text not null, ativo boolean not null default true);
create table public.pontos(id uuid primary key default gen_random_uuid(), colaborador_id uuid not null references public.profiles(id), posto_id uuid not null references public.postos(id), tipo text not null check(tipo in ('Entrada','Saída','Início intervalo','Fim intervalo')), registrado_em timestamptz not null default now(), latitude double precision not null, longitude double precision not null, distancia_m double precision not null, dentro boolean not null);
create table public.documentos(id uuid primary key default gen_random_uuid(), colaborador_id uuid not null references public.profiles(id), tipo text not null, validade date, arquivo text not null, criado_em timestamptz not null default now(), check(split_part(arquivo,'/',1)=colaborador_id::text));
create table public.auditoria(id bigint generated always as identity primary key, ator uuid, tabela text not null, operacao text not null, registro_id text, criado_em timestamptz default now());
do $$ declare t text; begin foreach t in array array['profiles','user_roles','postos','vinculos','pontos','documentos','auditoria'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy profile_admin on public.profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy roles_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy postos_admin on public.postos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy vinculos_admin on public.vinculos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy vinculos_read on public.vinculos for select to authenticated using(colaborador_id=auth.uid() and public.is_active());
create policy postos_read on public.postos for select to authenticated using(public.is_active() and exists(select 1 from public.vinculos v where v.posto_id=postos.id and v.colaborador_id=auth.uid() and v.ativo));
create policy pontos_read on public.pontos for select to authenticated using(public.is_admin() or colaborador_id=auth.uid());
create policy docs_read on public.documentos for select to authenticated using(public.is_admin() or colaborador_id=auth.uid());
create policy docs_insert on public.documentos for insert to authenticated with check(colaborador_id=auth.uid() and public.is_active());
create policy audit_read on public.auditoria for select to authenticated using(public.is_admin());
create function public.registrar_ponto(p_posto uuid,p_tipo text,p_lat double precision,p_lon double precision) returns public.pontos language plpgsql security definer set search_path='' as $$ declare p public.postos; d double precision; r public.pontos; begin
if not public.is_active() or not exists(select 1 from public.vinculos where colaborador_id=auth.uid() and posto_id=p_posto and ativo) then raise exception 'Sem vínculo ativo'; end if;
if p_lat is null or p_lon is null or not (p_lat between -90 and 90 and p_lon between -180 and 180) then raise exception 'Localização inválida'; end if;
select * into strict p from public.postos where id=p_posto;
d:=12742000*asin(sqrt(least(1.0,power(sin(radians(p_lat-p.latitude)/2),2)+cos(radians(p.latitude))*cos(radians(p_lat))*power(sin(radians(p_lon-p.longitude)/2),2))));
insert into public.pontos(colaborador_id,posto_id,tipo,latitude,longitude,distancia_m,dentro) values(auth.uid(),p_posto,p_tipo,p_lat,p_lon,d,d<=p.raio) returning * into r; return r; end $$;
revoke all on function public.registrar_ponto(uuid,text,double precision,double precision) from public;
grant execute on function public.registrar_ponto(uuid,text,double precision,double precision) to authenticated;
insert into storage.buckets(id,name,public) values('gestposto-documentos','gestposto-documentos',false);
create policy gestposto_storage_read on storage.objects for select to authenticated using(bucket_id='gestposto-documentos' and (public.is_admin() or (storage.foldername(name))[1]=auth.uid()::text));
create policy gestposto_storage_insert on storage.objects for insert to authenticated with check(bucket_id='gestposto-documentos' and public.is_active() and (storage.foldername(name))[1]=auth.uid()::text);
commit;
